// Offline support for the published build. service-worker-assets.js is generated by the build and lists every file.
importScripts('./service-worker-assets.js');

const cachePrefix = 'social-tennis-';
const cacheName = `${cachePrefix}${self.assetsManifest.version}`;
// Relative to this script, so it works from the site root and from a repository subpath alike.
const scopeUrl = new URL('./', self.location).href;
const indexUrl = new URL('index.html', scopeUrl).href;
const offlineAssetsInclude = [/\.dll$/, /\.pdb$/, /\.wasm$/, /\.html$/, /\.js$/, /\.json$/, /\.css$/, /\.woff2?$/, /\.png$/, /\.jpe?g$/, /\.gif$/, /\.ico$/, /\.svg$/, /\.webmanifest$/, /\.blat$/, /\.dat$/];
const offlineAssetsExclude = [/^service-worker\.js$/];

self.addEventListener('install', event => event.waitUntil(onInstall()));
self.addEventListener('activate', event => event.waitUntil(onActivate()));
self.addEventListener('fetch', event => event.respondWith(onFetch(event)));

async function onInstall() {
    // No integrity check on purpose: the deploy step rewrites <base href> in index.html after the build,
    // which would make that file fail a hash check and break installation.
    const assets = self.assetsManifest.assets
        .filter(asset => offlineAssetsInclude.some(pattern => pattern.test(asset.url)))
        .filter(asset => !offlineAssetsExclude.some(pattern => pattern.test(asset.url)));

    const cache = await caches.open(cacheName);
    await cache.addAll(assets.map(asset => new Request(asset.url, { cache: 'no-cache' })));
    await self.skipWaiting();
}

async function onActivate() {
    const keys = await caches.keys();
    await Promise.all(keys
        .filter(key => key.startsWith(cachePrefix) && key !== cacheName)
        .map(key => caches.delete(key)));
    await self.clients.claim();
}

async function onFetch(event) {
    const request = event.request;
    if (request.method !== 'GET') {
        return fetch(request);
    }

    const cache = await caches.open(cacheName);
    // Deep links such as /players all load the app shell, which routes on the client.
    const cached = request.mode === 'navigate'
        ? await cache.match(indexUrl)
        : await cache.match(request);
    return cached ?? fetch(request);
}
